#!/usr/bin/env python3
"""Stage the working tree as per-feature commits (H4 -> H5 -> H6), splitting
files whose hunks mix features.

Lossless-by-construction: every added line is attributed to exactly one
feature via the "[H4]"/"[H5]"/"[H6]" tag on the nearest preceding added
comment (all new blocks carry one); the concatenation of per-feature states
must reproduce the working tree byte-for-byte, asserted at the end.

  python3 /tmp/splitfeat.py dry     # report only
  python3 /tmp/splitfeat.py apply   # stage + commit each feature
"""
import difflib
import subprocess
import sys
from pathlib import Path

WT = "/home/sdc/gem5-fi-ding/.claude/worktrees/lsu-mdspec-20261019"
TAGS = {"[H4]": "H4", "[H5]": "H5", "[H6]": "H6"}
ORDER = ["H4", "H5", "H6"]
FILES = [
    ("CHAOS/gem5/src/cpu/o3/CHAOSPropagation/CHAOSPropagation.hh", "H5"),
    ("CHAOS/gem5/src/cpu/o3/CHAOSPropagation/CHAOSPropagation.cc", "H5"),
    ("CHAOS/gem5/src/mem/cache/base.cc", "H4"),
    ("CHAOS/gem5/src/mem/cache/cache.cc", "H5"),
    ("CHAOS/gem5/src/mem/cache/prefetch/CHAOSPrefetch/CHAOSPrefetch.cc", "H5"),
    ("CHAOS/gem5/src/mem/cache/prefetch/CHAOSPrefetch/CHAOSPrefetch.hh", "H5"),
    ("CHAOS/gem5/src/mem/cache/prefetch/queued.cc", "H5"),
    ("CHAOS/gem5/src/arch/arm/CHAOSExMon/CHAOSExMon.cc", "H6"),
    ("CHAOS/gem5/src/arch/arm/CHAOSExMon/CHAOSExMon.hh", "H6"),
    ("tools/lsu_prop_fields.py", "H5"),
    ("tests/test_lsu_hook_cpf.py", "H5"),
]


def head_of(path):
    r = subprocess.run(["git", "-C", WT, "show", f"HEAD:{path}"],
                       capture_output=True, text=True)
    assert r.returncode == 0, path
    return r.stdout.splitlines(keepends=True)


def cur_of(path):
    return (Path(WT) / path).read_text(encoding="utf-8").splitlines(keepends=True)


def analyse(path, default):
    head, final = head_of(path), cur_of(path)
    sm = difflib.SequenceMatcher(None, head, final, autojunk=False)
    ops = sm.get_opcodes()
    feat = {}
    cur = default
    for tag, i1, i2, j1, j2 in ops:
        if tag in ("insert", "replace"):
            for j in range(j1, j2):
                body = final[j].strip()
                for t, name in TAGS.items():
                    if body.startswith(("//", "#", "*", "/*")) and t in body:
                        cur = name
                feat[j] = cur
    return head, final, ops, feat


def state_for(head, final, ops, feat, wanted, with_deletes):
    out = []
    for tag, i1, i2, j1, j2 in ops:
        if tag == "equal":
            out.extend(head[i1:i2])
        elif tag == "delete":
            if with_deletes:
                pass                     # deletions dropped => applied
            else:
                out.extend(head[i1:i2])
        else:
            for j in range(j1, j2):
                if feat.get(j) in wanted:
                    out.append(final[j])
    return out


def main():
    mode = sys.argv[1]
    plans = {}
    for path, default in FILES:
        head, final, ops, feat = analyse(path, default)
        if head == final:
            continue
        plans[path] = (head, final, ops, feat)
        counts = {f: sum(1 for v in feat.values() if v == f) for f in ORDER}
        print(f"{path}: added={len(feat)} {counts}")

    # lossless assertion
    for path, (head, final, ops, feat) in plans.items():
        allf = state_for(head, final, ops, feat, set(ORDER), True)
        assert allf == final, f"LOSSY SPLIT: {path}"
    print("lossless: OK (per-feature states reproduce the working tree)")

    if mode == "dry":
        return 0

    for idx, f in enumerate(ORDER):
        subprocess.run(["git", "-C", WT, "add", "-N", "--"] +
                       [p for p in plans], check=False,
                       capture_output=True)
        for path, (head, final, ops, feat) in plans.items():
            prev = state_for(head, final, ops, feat, set(ORDER[:idx]),
                             idx == len(ORDER) - 1)
            cur = state_for(head, final, ops, feat, set(ORDER[:idx + 1]),
                            idx == len(ORDER) - 1)
            if prev == cur:
                continue
            patch = "".join(difflib.unified_diff(
                prev, cur, fromfile=f"a/{path}", tofile=f"b/{path}", n=3))
            r = subprocess.run(["git", "-C", WT, "apply", "--cached", "-"],
                               input=patch, text=True, capture_output=True)
            if r.returncode != 0:
                print("FAIL", f, path, r.stderr[:400])
                return 1
            print("staged", f, path)
        c = subprocess.run(["git", "-C", WT, "commit", "-F",
                            f"/tmp/msg_{f}.txt"], capture_output=True, text=True)
        print("commit", f, "rc=", c.returncode, c.stdout.strip()[:90],
              c.stderr.strip()[:200])
        if c.returncode != 0:
            return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

